@testable import PhotoCraft

private final class PatternFillGate:@unchecked Sendable{let condition=NSCondition();var ready=false;func wait(){condition.lock();while !ready{condition.wait()};condition.unlock()};func release(){condition.lock();ready=true;condition.broadcast();condition.unlock()}}
final class PatternPixelFillWorkflowTests:XCTestCase{
  func pattern(_ depth:PixelDepth = .u8,color:Pixel=Pixel(1,0,0))throws->RasterPattern{var pixels=try Surface(width:2,height:2,depth:depth,fill:color);pixels.setPixel(x:1,y:1,.clear);return try RasterPattern(name:"Owned pattern",surface:pixels,id:"owned-pattern")}
  func fixture(_ depth:PixelDepth = .u8)throws->CraftDocument{var d=try PixelFillStrokeWorkflowTests().fixture(depth);d.patterns=[try pattern(depth)];return d}
  @MainActor func testNativeCustomPatternPickerNamesSelectionDisabledLoadingAndStateSchema()throws{
    _=NSApplication.shared;let asset=try pattern(),picker=PixelPaintAccessory(kind:.fill,settings:.init(),scalar:false,patterns:[asset],selectedPatternID:asset.id);picker.contents.selectItem(withTitle:"Pattern");picker.contentsChanged();XCTAssertTrue(picker.color.isHidden);XCTAssertFalse(picker.customPattern.isHidden);XCTAssertEqual(picker.sourceLabel.stringValue,"Custom Pattern:");XCTAssertEqual(picker.chosenPattern,asset);picker.contents.selectItem(withTitle:"Color…");picker.contentsChanged();XCTAssertFalse(picker.color.isHidden);XCTAssertTrue(picker.customPattern.isHidden);let unavailable=PixelPaintAccessory(kind:.fill,settings:.init(),scalar:false,patterns:[]);XCTAssertFalse(try XCTUnwrap(unavailable.contents.item(withTitle:"Pattern")).isEnabled);let loading=PixelPaintAccessory(kind:.fill,settings:.init(),scalar:false,patterns:[asset],patternBusy:true);XCTAssertFalse(loading.customPattern.isEnabled)
    let s=EditorStore(document:try fixture(),patterns:PatternLibrary());defer{s.renderTask?.cancel()};XCTAssertTrue(s.canFillWithPattern);let state=try JSONDecoder().decode(AutomationValue.self,from:JSONSerialization.data(withJSONObject:s.pixelPaintState));XCTAssertNoThrow(try BrushAPI.merge(state,schema:PixelPaintAPI.stateSchema));XCTAssertEqual(s.pixelFillPatterns.first?.id,asset.id)
  }
  @MainActor func testNativeCapturedPresetSurvivesLibraryChangeUndoActions42AndArchive()async throws{
    var source=try fixture();source.patterns=nil;let library=PatternLibrary(),red=try pattern(),blue=try pattern(color:Pixel(0,0,1));try await library.install([red]);let s=EditorStore(document:source,patterns:library);defer{s.geometryTask?.cancel();s.renderTask?.cancel()};try s.session.startActionRecording(name:"Pattern");let gate=PatternFillGate();defer{gate.release()};s.pixelPaintPreparation={_,request in gate.wait();try Task.checkCancellation();return .pixelPaint(request)};var settings=PixelPaintSettings(color:.clear);settings.opacity=0.5;s.applyPixelPaint(.fill,settings:settings,pattern:red);let task=try XCTUnwrap(s.geometryTask);try await library.install([blue]);gate.release();await task.value;XCTAssertNil(s.error);var expected=source;try Command.pixelPaint(.init(.fill,target:.layer(source.layers[0].id),settings:settings,pattern:red)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(s.lastPixelFillContents,"Pattern");XCTAssertEqual(s.session.undoStack.count,1);var file=ActionLibraryFile();file.actions=[try XCTUnwrap(s.session.actionRecording?.snapshot)];let bytes=try file.encoded();XCTAssertEqual(try ActionLibraryFile.decode(bytes).version,42);var wrong=try XCTUnwrap(JSONSerialization.jsonObject(with:bytes) as? [String:Any]);wrong["version"]=41;XCTAssertThrowsError(try ActionLibraryFile.decode(JSONSerialization.data(withJSONObject:wrong)));var replay=source;try ActionLibraryFile.decode(bytes).actions[0].apply(to:&replay);XCTAssertEqual(replay,s.document);XCTAssertEqual(try NativeArchive.decode(NativeArchive.encodeChunked(s.document)),s.document);_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source)
  }
  @MainActor func testHTTPThreeDepthsProfilesTargetsAndPlacementShareNativeBytes()async throws{
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let s=doc.store;for depth in PixelDepth.allCases{for targetKind in ["layer","mask","channel"]{for shifted in [false,true]{var source=try self.fixture(depth);source.workingICC=try ColorManagement.importedProfile(XCTUnwrap(CGColorSpace(name:CGColorSpace.displayP3)?.copyICCData() as Data?),depth:depth);s.session=EditorSession(document:source);s.maskEditingLayerID=nil;s.alphaEditingID=nil;s.componentTarget = .composite;let id=source.layers[0].id,target:PixelPaintTarget;var params:[String:Any]=["patternID":"owned-pattern","opacity":0.5,"mode":"Multiply"];switch targetKind{case "mask":s.selectMask(id);target = .mask(id);params["layerID"]=id.uuidString;params["mask"]=true;case "channel":let channel=try XCTUnwrap(source.alphaChannels?.first?.id);try s.selectAlphaChannel(channel);target = .channel(.alpha(channel));params["target"]=channel.uuidString;default:target = .layer(id);params["layerID"]=id.uuidString};var placement:PatternPlacement?;if shifted{var value=PatternPlacement();value.phaseX=1;value.phaseY = -1;placement=value;params["placement"]=["phaseX":1,"phaseY":-1]};try service.share(doc);let code=try await h.edit(service,doc,"pixels.fill",params);XCTAssertEqual(code,200);var settings=PixelPaintSettings(color:.white);settings.opacity=0.5;settings.mode = .multiply;var expected=source;try Command.pixelPaint(.init(.fill,target:target,settings:settings,pattern:source.patterns![0],placement:placement)).apply(to:&expected);XCTAssertEqual(s.document,expected);XCTAssertEqual(try NativeArchive.encodeChunked(s.document),try NativeArchive.encodeChunked(expected));XCTAssertEqual(s.nativePixelPaintTarget,target);_=await s.requestHistory(redo:false).value;XCTAssertEqual(s.document,source)}}}}
  }
  @MainActor func testInvalidAmbiguousMissingStaleBusyAndRevokedPatternRequestsAreAtomic()async throws{
    let h=AutomationTests();try await h.withService(pressedMouseButtons:{0}){service,doc in let source=try self.fixture(),s=doc.store;s.session=EditorSession(document:source);try service.share(doc);let params:[String:Any]=["layerID":source.layers[0].id.uuidString,"patternID":"owned-pattern"];for extra:[String:Any] in [["color":[1,1,1,1]],["patternID":17],["placement":["scale":0]],["placement":["unknown":1]],["opacity":2],["mode":"bad"],["unknown":1]]{let code=try await h.edit(service,doc,"pixels.fill",params.merging(extra){_,b in b});XCTAssertEqual(code,400);XCTAssertEqual(s.document,source)};let missing=try await h.edit(service,doc,"pixels.fill",params.merging(["patternID":"not-present"]){_,b in b});XCTAssertEqual(missing,404);let colorPlacement=try await h.edit(service,doc,"pixels.fill",["layerID":source.layers[0].id.uuidString,"color":[1,1,1,1],"placement":["phaseX":1]]);XCTAssertEqual(colorPlacement,400);let stale=try await h.edit(service,doc,"pixels.fill",params,revision:"old");XCTAssertEqual(stale,409);s.beginTransform();let busy=try await h.edit(service,doc,"pixels.fill",params);XCTAssertEqual(busy,409);s.cancelTransform();let gate=PatternFillGate();defer{gate.release()};s.pixelPaintPreparation={_,request in gate.wait();try Task.checkCancellation();return .pixelPaint(request)};let task=Task{try await h.edit(service,doc,"pixels.fill",params)};let until=Date().addingTimeInterval(10);while !s.geometryBusy && Date()<until{await Task.yield()};service.revoke(try XCTUnwrap(service.shares.first?.id));gate.release();let code=try await task.value;XCTAssertEqual(code,409);XCTAssertEqual(s.document,source)}
  }
  @MainActor func testNativeCancelledPatternWorkAndDocumentPriorityKeepDataAndCursorPolicy()async throws{
    let source=try fixture(),s=EditorStore(document:source,patterns:PatternLibrary()),asset=try XCTUnwrap(source.patterns?.first);defer{s.geometryTask?.cancel();s.renderTask?.cancel()};let replacement=try pattern(color:Pixel(0,0,1));try await s.patterns.install([replacement]);XCTAssertEqual(s.pixelFillPatterns.filter{$0.id==asset.id},[asset]);let gate=PatternFillGate();defer{gate.release()};s.pixelPaintPreparation={_,request in gate.wait();try Task.checkCancellation();return .pixelPaint(request)};s.applyPixelPaint(.fill,settings:.init(),pattern:asset);let task=try XCTUnwrap(s.geometryTask);s.geometryTask?.cancel();gate.release();await task.value;XCTAssertEqual(s.document,source);XCTAssertTrue(s.session.undoStack.isEmpty);let canvas=CraftCanvas(store:s),flags:[NSEvent.ModifierFlags]=[.control,.command,.option,.shift];for bits in 0..<16{let f=flags.enumerated().reduce(NSEvent.ModifierFlags()){r,p in bits&(1<<p.offset) != 0 ? r.union(p.element):r};canvas.updateCursorModifiers(f);let before=canvas.toolCursor;_ = PixelPaintAccessory(kind:.fill,settings:.init(),scalar:false,patterns:[asset]);canvas.updateCursorModifiers(f);XCTAssertEqual(canvas.toolCursor,before)};XCTAssertEqual(AutomationCommand.definitions.count, AutomationTests.expectedCommandCount);XCTAssertEqual(ActionLibraryFile.maximumVersion,48)
  }
